CREATE POLICY "Admins upload excellence files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'excellence' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins update excellence files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'excellence' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins delete excellence files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'excellence' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins read excellence files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'excellence' AND public.has_role(auth.uid(), 'admin'));